|
          RAW='${{ toJson(github.event.client_payload) }}'

          # Normalize payload
          if [ "$RAW" = "null" ] || [ -z "$RAW" ]; then
            echo '{"_empty": true}' > payload.json
          else
            echo "$RAW" > payload.json
          fi

          node - <<'NODE'
          const fs = require('fs');

          let data;
          try {
            data = JSON.parse(fs.readFileSync('payload.json','utf8'));
          } catch (e) {
            console.error("Malformed JSON");
            process.exit(1);
          }

          // Reject null explicitly
          if (data === null) {
            console.error("Null payload rejected");
            process.exit(1);
          }

          // Allow empty but mark it
          if (data._empty === true) {
            console.log("Empty witness accepted.");
            process.exit(0);
          }

          // Reject empty object (silent noise)
          if (typeof data === 'object' && Object.keys(data).length === 0) {
            console.error("Empty object payload rejected");
            process.exit(1);
          }

          // Size guard
          const size = JSON.stringify(data).length;
          if (size > 5000) {
            console.error("Payload too large");
            process.exit(1);
          }

          console.log("Payload validated.");
          NODE

