[{"path":"./core-scientific/.github/workflows/witness-proxy.yml","kind":"Hidden","annotation":"this step","start":{"row":17,"column":8},"end":{"row":71,"column":0},"feature":"name: Validate and create witness issue
        uses: actions/github-script@v7
        env:
          WITNESS_PAYLOAD: ${{ inputs.payload }}
        with:
          github-token: ${{ github.token }}
          script: |

            const raw = process.env.WITNESS_PAYLOAD;
            let payload;

            try {
              payload = JSON.parse(raw);
            } catch (err) {
              core.setFailed("Invalid JSON payload.");
              return;
            }

            if (typeof payload.id !== "string") {
              core.setFailed("Missing unique 'id' (string required).");
              return;
            }

            if (typeof payload.timestamp !== "number") {
              core.setFailed("Invalid or missing 'timestamp'.");
              return;
            }

            if (typeof payload.weight !== "number" || payload.weight < 0) {
              core.setFailed("Invalid or missing 'weight'.");
              return;
            }

            const search = await github.rest.search.issuesAndPullRequests({
              q: `repo:${context.repo.owner}/${context.repo.repo} in:title "${payload.id}"`
            });

            if (search.data.total_count > 0) {
              core.setFailed("Duplicate event ID detected.");
              return;
            }

            const body =
              `id: ${payload.id}\n` +
              `timestamp: ${payload.timestamp}\n` +
              `weight: ${payload.weight}\n` +
              `origin: ${payload.origin || "unknown"}\n`;

            await github.rest.issues.create({
              owner: context.repo.owner,
              repo: context.repo.repo,
              title: payload.id,
              body: body
            });
"},{"path":"./core-scientific/.github/workflows/witness-proxy.yml","kind":"Primary","annotation":"action is not pinned to a hash (required by blanket policy)","start":{"row":18,"column":14},"end":{"row":18,"column":38},"feature":"actions/github-script@v7"}]
